cy.visit('/publish');
// ProtectedRoute 应当把未登录用户重定向到 /login
cy.url({
  timeout: 6000
}).should('match', /login|home|\/$/);

cy.intercept('POST', '**/ai/analyze-and-save').as('aiSave');
cy.intercept('POST', '**/products**').as('createProduct');
cy.loginAsTestUser().then(() => {
  cy.visit('/publish');
  // 上传图片到隐藏 input
  cy.get('input[type=file]').first().selectFile('cypress/fixtures/test_product.png', {
    force: true
  });
  // 点 AI Smart Publish 按钮
  cy.contains('button', /AI Smart Publish/i).click();
  // CA2 目标：AI 响应 < 8s
  const start = Date.now();
  cy.wait('@aiSave', {
    timeout: 15000
  }).then(interception => {
    const elapsed = Date.now() - start;
    expect(interception.response.statusCode).to.eq(200);
    expect(elapsed).to.be.lessThan(8000);
    // AI 应返回 title/description/category
    expect(interception.response.body.data).to.have.keys('title', 'description', 'category', 'keywords');
  });
  // 等表单被 AI 数据填充
  cy.get('input[placeholder*="title"]', {
    timeout: 5000
  }).should('not.have.value', '');
  // 加价格（AI 不填这个字段）
  cy.get('input[placeholder="0.00"]').clear().type('29.99');
  // 提交
  cy.contains('button', /Confirm.*Publish/i).click();
  cy.wait('@createProduct').then(interception => {
    expect([200, 201]).to.include(interception.response.statusCode);
  });
});
